import { readFile, writeFile } from "node:fs/promises";
import { createWorkspace, createForks } from "@tigrisdata/agent-kit";
import { put, get } from "@tigrisdata/storage";

const TRIAL_ID_PATH = "/logs/artifacts/trial_id";
const WRITE_DENIAL_LOG = "/home/user/tigris-task/write-denial.log";
const READBACK_PATH = "/home/user/tigris-task/readback.txt";

const normalizeBucketName = (name: string) =>
  name.toLowerCase().replace(/[^a-z0-9.-]/g, "-");

const stringifyError = (err: unknown): string => {
  if (!err) {
    return "Unknown error";
  }
  if (typeof err === "string") {
    return err;
  }
  const anyErr = err as Record<string, unknown>;
  const parts: string[] = [];
  const name = anyErr.name ?? "Error";
  const message = anyErr.message ?? String(err);
  parts.push(`${name}: ${message}`);

  const code = anyErr.code ?? anyErr.Code;
  if (code) {
    parts.push(`code=${String(code)}`);
  }

  const status =
    anyErr.statusCode ??
    (anyErr.$metadata as { httpStatusCode?: number } | undefined)?.httpStatusCode;
  if (status) {
    parts.push(`httpStatus=${String(status)}`);
  }

  const cause = anyErr.cause as Record<string, unknown> | undefined;
  if (cause) {
    const causeMsg = cause.message ?? cause.code ?? cause.Code;
    if (causeMsg) {
      parts.push(`cause=${String(causeMsg)}`);
    }
  }

  return parts.join(" | ");
};

const fail = (message: string): never => {
  console.error(message);
  process.exit(1);
};

const main = async () => {
  const trialIdRaw = (await readFile(TRIAL_ID_PATH, "utf-8")).trim();
  if (!trialIdRaw) {
    fail(`Trial id missing from ${TRIAL_ID_PATH}`);
  }

  const trialId = trialIdRaw.toLowerCase();
  const workspaceNameRaw = `harbor-ro-${trialId}`;
  const workspaceName = normalizeBucketName(workspaceNameRaw);

  const workspaceResult = await createWorkspace(workspaceName, {
    ttl: { days: 1 },
    enableSnapshots: true,
    credentials: { role: "Editor" },
  });

  if (workspaceResult.error) {
    fail(`createWorkspace failed: ${stringifyError(workspaceResult.error)}`);
  }

  const workspaceData = workspaceResult.data;
  if (!workspaceData?.credentials) {
    fail("createWorkspace missing credentials");
  }

  const workspaceBucket = workspaceData.workspace?.bucket ?? workspaceData.bucket;
  if (!workspaceBucket) {
    fail("createWorkspace missing workspace bucket name");
  }

  const { accessKeyId, secretAccessKey } = workspaceData.credentials;
  if (!accessKeyId || !secretAccessKey) {
    fail("Editor credentials incomplete");
  }

  const editorPut = await put("notes/welcome.txt", "hello readonly", {
    config: {
      bucket: workspaceBucket,
      accessKeyId,
      secretAccessKey,
    },
  });

  if (editorPut.error) {
    fail(`Editor put failed: ${stringifyError(editorPut.error)}`);
  }

  const forkPrefix = normalizeBucketName(`harbor-ro-${trialId}-readonly`);
  const forkResult = await createForks(workspaceBucket, 1, {
    prefix: forkPrefix,
    credentials: { role: "ReadOnly" },
  });

  if (forkResult.error) {
    fail(`createForks failed: ${stringifyError(forkResult.error)}`);
  }

  const fork = forkResult.data?.forks?.[0];
  if (!fork?.credentials) {
    fail("createForks missing fork credentials");
  }

  const forkBucket = fork.bucket ?? `${forkPrefix}-0`;
  const readonlyAccessKeyId = fork.credentials.accessKeyId;
  const readonlySecretAccessKey = fork.credentials.secretAccessKey;

  if (!readonlyAccessKeyId || !readonlySecretAccessKey) {
    fail("ReadOnly credentials incomplete");
  }

  const readonlyPut = await put("notes/forbidden.txt", "should be rejected", {
    config: {
      bucket: forkBucket,
      accessKeyId: readonlyAccessKeyId,
      secretAccessKey: readonlySecretAccessKey,
    },
  });

  if (!readonlyPut.error) {
    fail("ReadOnly put unexpectedly succeeded");
  }

  const denialMessage = stringifyError(readonlyPut.error);
  if (!denialMessage.trim()) {
    fail("ReadOnly put returned empty error message");
  }

  await writeFile(WRITE_DENIAL_LOG, denialMessage, "utf-8");

  const readonlyGet = await get("notes/welcome.txt", "string", {
    config: {
      bucket: forkBucket,
      accessKeyId: readonlyAccessKeyId,
      secretAccessKey: readonlySecretAccessKey,
    },
  });

  if (readonlyGet.error) {
    fail(`ReadOnly get failed: ${stringifyError(readonlyGet.error)}`);
  }

  if (readonlyGet.data !== "hello readonly") {
    fail(`ReadOnly get returned unexpected body: ${String(readonlyGet.data)}`);
  }

  await writeFile(READBACK_PATH, readonlyGet.data, "utf-8");
};

main().catch((err) => {
  fail(`Unexpected failure: ${stringifyError(err)}`);
});
